[
  {
    "pd_harm_distress": "stomach just twists thinking about those five men",
    "ce_mental_state_attribution": "not knowing what's coming",
    "pd_decision_conflict": "I can't just act on instinct with this weight on me"
  },
  {
    "pd_harm_distress": "thought of those workers being hit makes me feel sick",
    "pd_decision_conflict": "It feels too heavy to just choose in an instant",
    "sys_consequence_reasoning": "it wouldn't hurt anyone else"
  },
  {
    "pd_harm_distress": "There's this ache in my chest just imagining",
    "ce_mental_state_attribution": "them not knowing",
    "pd_decision_conflict": "But I keep freezing"
  },
  {
    "pd_harm_distress": "feeling hollow, sick almost, like the air's gone thin",
    "sys_consequence_reasoning": "no one else gets hurt",
    "pd_decision_conflict": "my hands won't move"
  },
  {
    "pd_harm_distress": "My throat's closed up just thinking about those men",
    "pd_decision_conflict": "torn between doing something and just wanting the moment to pass"
  },
  {
    "pd_harm_distress": "my legs feel weak just watching this unfold",
    "pd_decision_conflict": "afraid of the finality of choosing"
  },
  {
    "pd_harm_distress": "it makes my chest ache",
    "ce_mental_state_attribution": "how helpless they'd be",
    "pd_decision_conflict": "I just can't rush this"
  },
  {
    "pd_harm_distress": "recoils at the thought of those men getting hurt",
    "pd_decision_conflict": "my hand won't cooperate yet"
  },
  {
    "pd_harm_distress": "I feel this heaviness settle over me, almost like nausea",
    "pd_decision_conflict": "committing to pulling that lever feels enormous right now",
    "ce_mental_state_attribution": "unaware"
  },
  {
    "pd_harm_distress": "I feel sick just imagining what happens",
    "pd_decision_conflict": "bracing against making the call"
  }
]
